"208 :   void addOp(String op, boolean binOp) {
209 :     maybeEndStatement();
210 : 
211 :     char first = op.charAt(0);
212 :     char prev = getLastChar();
213 : 
214 :     if ((first == '+' || first == '-') && prev == first) {
215 :       // This is not pretty printing. This is to prevent misparsing of
216 :       // things like "x + ++y" or "x++ + ++y"
217 :       append(" ");
218 :     } else if (Character.isLetter(first) &&
219 :                isWordChar(prev)) {
220 :       // Make sure there is a space after e.g. instanceof , typeof
221 :       append(" ");
222 :     } else if (prev == '-' && first == '>') {
223 :       // Make sure that we don't emit -->
224 :       append(" ");
225 :     }
226 : 
227 :     // Allow formating around the operator.
228 :     appendOp(op, binOp);
229 : 
230 :     // Line breaking after an operator is always safe. Line breaking before an
231 :     // operator on the other hand is not. We only line break after a bin op
232 :     // because it looks strange.
233 :     if (binOp) {
234 :       maybeCutLine();
235 :     }
236 :   }"

"609 :   private static String toSource(Node root, Format outputFormat,
610 :                                  boolean lineBreak,  int lineLengthThreshold,
611 :                                  SourceMap sourceMap,
612 :                                  SourceMap.DetailLevel sourceMapDetailLevel,
613 :                                  Charset outputCharset,
614 :                                  boolean tagAsStrict) {
615 :     Preconditions.checkState(sourceMapDetailLevel != null);
616 : 
617 :     boolean createSourceMap = (sourceMap != null);
618 :     MappedCodePrinter mcp =
619 :         outputFormat == Format.COMPACT
620 :         ? new CompactCodePrinter(
621 :             lineBreak, lineLengthThreshold,
622 :             createSourceMap, sourceMapDetailLevel)
623 :         : new PrettyCodePrinter(
624 :             lineLengthThreshold, createSourceMap, sourceMapDetailLevel);
625 :     CodeGenerator cg =
626 :         outputFormat == Format.TYPED
627 :         ? new TypedCodeGenerator(mcp, outputCharset)
628 :         : new CodeGenerator(mcp, outputCharset);
629 : 
630 :     if (tagAsStrict) {
631 :       cg.tagAsStrict();
632 :     }
633 : 
634 :     cg.add(root);
635 :     mcp.endFile();
636 : 
637 :     String code = mcp.getCode();
638 : 
639 :     if (createSourceMap) {
640 :       mcp.generateSourceMap(sourceMap);
641 :     }
642 : 
643 :     return code;
644 :   }"

